contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) ensure MinSum and LogFile are set and contract initialized appropriately,
    // 2) fund the caller's account in c via Put, advancing unlockTime to past so Collect can succeed,
    // 3) call Collect and check that if Collect did not revert then balances decreased by _am.

    receive() external payable {}

    function run(uint put_lock, uint put_amount, uint collect_amount, uint minSum, address logAddr) public payable {
        require(msg.sender != address(0)); // harmless precondition to keep parameters usable
        // fund this test contract so it can call c with value
        // ensure we have enough Ether to call Put with put_amount
        require(address(this).balance >= put_amount);

        // Set MinSum and LogFile and mark initialized only if not yet initialized.
        // These calls may revert if intitalized is already true; but c is fresh so they should succeed.
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Read holder balance before Put
        (uint before_balance, ) = getAcc();
        uint beforeContractBal = address(c).balance;

        // Call Put to add funds for this InvMutTest (it is the msg.sender from c's perspective)
        c.Put{value: put_amount}(put_lock);

        // After Put read balance and contract balance
        (uint mid_balance, ) = getAcc();
        uint midContractBal = address(c).balance;

        // Now we need unlockTime to be in the past so Collect can succeed: we assume put_lock small and block.timestamp+put_lock set unlockTime
        // We cannot fast-forward block.timestamp; instead choose collect only if block.timestamp > unlockTime by making put_lock == 0
        // To keep generality, allow collect attempt and observe revert flag
        bool reverted;
        // Ensure contract has enough Ether to send collect_amount back
        // c balance currently midContractBal, require it is >= collect_amount to allow transfer if conditions met
        // But we cannot require that because we want to detect revert. So we attempt and catch revert.

        // Try Collect
        try c.Collect{value: 0}(collect_amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        (uint after_balance, ) = getAcc();
        uint afterContractBal = address(c).balance;

        // Assert: if Collect did NOT revert, then the holder balance decreased by collect_amount and contract balance decreased by collect_amount.
        assert(reverted || (after_balance + collect_amount == mid_balance && afterContractBal + collect_amount == midContractBal));
    }

    // helper to read Acc[msg.sender] using c's public getter; acc returns (unlockTime, balance) but in contract C it's Holder public mapping so getter signature is (uint,uint)
    function getAcc() internal returns (uint,uint) {
        // The auto-generated getter for mapping (address => Holder) public Acc returns (uint unlockTime, uint balance)
        return c.Acc(address(this));
    }
}

