    // collect_amount: amount to attempt to Collect
    // minSum: value to set as MinSum
    // logAddr: address for LogFile
    function run(uint put_lock, uint put_amount, uint collect_amount, uint minSum, address logAddr) public payable {
        // need funds to Put
        require(address(this).balance >= put_amount, "insufficient funds for Put");

        // Initialize c (only allowed before intitalized flag set)
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Do a Put sending put_amount
        c.Put{value: put_amount}(put_lock);

        // Read holder recorded balance before Collect attempt
        (, uint holderBefore) = c.Acc(address(this));
        // Read contract's overall balance before Collect
        uint contractBalBefore = address(c).balance;

        // Attempt Collect and record revert status
        bool reverted;
        try c.Collect{value: 0}(collect_amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder recorded balance after Collect
        (, uint holderAfter) = c.Acc(address(this));
        // Read contract's overall balance after Collect
        uint contractBalAfter = address(c).balance;

        // If Collect succeeded, then the recorded holder balance should equal the contract balance that is attributable to this holder.
        // We cannot directly observe per-holder Ether in the contract except via Acc(...).balance, but the invariant we assert is:
        // if Collect did not revert then holderAfter <= holderBefore and contractBalAfter <= contractBalBefore,
        // and the decrease in holder's recorded balance equals the decrease in contract's total balance (i.e., both decreased by the same amount).
        // This avoids subtraction that could underflow in the assert by comparing sums instead.

        assert(reverted || (holderAfter <= holderBefore && contractBalAfter <= contractBalBefore && (holderAfter + (contractBalBefore - contractBalAfter) == holderBefore)));
    }
}

