contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will take parameters to call Put and Collect. amountPut is the Ether to send to Put.
    // collectAmt is the requested amount for Collect. lockTime is passed to Put. We require
    // the test contract to have enough balance to send amountPut.
    function run(uint amountPut, uint lockTime, uint collectAmt) public payable {
        require(address(this).balance >= amountPut, "insufficient test balance");
        // Read pre-state: holder balance for this contract (msg.sender is this test contract when calling c)
        C.Holder memory beforeHolder = c.Acc(address(this));
        uint beforeHolderBal = beforeHolder.balance;
        uint beforeCbal = address(c).balance;

        // Call Put sending Ether amountPut
        c.Put{value: amountPut}(lockTime);

        // Read post-state holder and contract balances
        C.Holder memory afterHolder = c.Acc(address(this));
        uint afterHolderBal = afterHolder.balance;
        uint afterCbal = address(c).balance;

        // Attempt Collect of collectAmt and observe revert or success
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final state
        C.Holder memory finalHolder = c.Acc(address(this));
        uint finalHolderBal = finalHolder.balance;
        uint finalCbal = address(c).balance;

        // General rule (single assert):
        // 1) Put must increase the holder's recorded balance by exactly amountPut, and the contract
        //    balance increases by at least amountPut (covers potential other simultaneous changes).
        // 2) If Collect succeeded (not reverted), then collectAmt could not exceed the holder's balance
        //    at time of call, and both the holder's balance and contract balance decreased by collectAmt.
        // 3) If Collect reverted, then the holder's balance and contract balance remain unchanged from after Put.
        assert(
            // Put effect: holder increased by amountPut and c balance increased accordingly
            afterHolderBal == beforeHolderBal + amountPut && afterCbal >= beforeCbal + amountPut
            &&
            (
                // Case: Collect succeeded
                (!reverted && finalHolderBal + collectAmt == afterHolderBal && finalCbal + collectAmt == afterCbal)
                ||
                // Case: Collect reverted -> no change
                (reverted && finalHolderBal == afterHolderBal && finalCbal == afterCbal)
            )
        );
    }

    // Allow receiving Ether so this test contract can be funded
    receive() external payable {}
}

