    // Inputs: amount to send with Put (putAmt), lock time for Put (lockTime), attempt to Collect collectAmt.
    function run(uint putAmt, uint lockTime, uint collectAmt) public payable {
        require(address(this).balance >= putAmt, "insufficient balance to fund Put");

        // Read initial observable state
        uint before_acc_balance = c.Acc(address(this)).balance;
        uint before_c_balance = address(c).balance;

        // Call Put by sending Ether via fallback or direct Put depending on lockTime; use Put explicitly
        c.Put{value: putAmt}(lockTime);

        // After Put, balances should reflect the deposit: contract's recorded balance for this address
        uint after_acc_balance = c.Acc(address(this)).balance;
        uint after_c_balance = address(c).balance;

        // Try to Collect collectAmt and record whether it reverted
        bool collect_reverted;
        try c.Collect{value: 0}(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        uint final_acc_balance = c.Acc(address(this)).balance;
        uint final_c_balance = address(c).balance;

        // General rule asserted:
        // 1) after_acc_balance equals before_acc_balance + putAmt
        // 2) after_c_balance equals before_c_balance + putAmt
