    // so it can have a balance in c by calling Put first. To avoid triggering add_uint256 overflow in c,
    // we keep amounts modest and ensure requires on address(this).balance.
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        // Ensure this test contract has enough Ether to fund Put
        require(address(this).balance >= putAmount);

        // Read before-values
        (, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // First fund c by calling Put (may revert). We record whether Put succeeded to decide expectations.
        bool putReverted;
        try c.Put{value: putAmount}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read middle-values after Put attempt
        (, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect with collectAmount. Collect may revert.
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

