        // - If Put reverted then midBal==beforeBal and midContractBal==beforeContractBal.
        // - If Put succeeded then midBal==beforeBal + putAmount and midContractBal==beforeContractBal + putAmount.
        // - If Collect reverted then afterBal==midBal and afterContractBal==midContractBal.
        // - If Collect succeeded then afterBal==midBal - collectAmount and afterContractBal==midContractBal - collectAmount.
        // We express this as one combined assert without performing subtraction that can underflow in the assert by
        // branching on the observed mid values (which are read from c) and using comparisons.

        // Build boolean conditions safely
        bool put_effect_ok = putReverted ? (midBal == beforeBal && midContractBal == beforeContractBal)
