contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: amount to try to collect, and an initial deposit to ensure some balance.
    function run(uint initialLock, uint deposit, uint collectAmt) public payable {
        // ensure this test contract can fund the deposit call
        require(address(this).balance >= deposit, "insufficient test funds");

        // ensure we start from a clean observation
        (uint beforeUnlock, uint beforeAccBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Make an initial deposit to potentially allow Collect to succeed.
        // We catch revert but continue: if Put reverts then state should remain unchanged.
        bool putReverted;
        try c.Put{value: deposit}(initialLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read state after Put attempt, before Collect
        (uint midUnlock, uint midAccBalance) = c.Acc(address(this));
        uint midContractBalance = address(c).balance;

        // Attempt Collect and record whether it reverted.
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        (uint afterUnlock, uint afterAccBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // The rule: if Collect succeeded then both the recorded per-account balance and
        // the contract's Ether balance decreased by exactly collectAmt compared to before the Collect call;
        // if Collect reverted then neither of those balances changed by the Collect call.
        // Note: the Put call may or may not have changed state; we compare post-Collect to pre-Collect (mid* values).
        assert(
            (collectReverted && afterAccBalance == midAccBalance && afterContractBalance == midContractBalance)
            || (!collectReverted && afterAccBalance + collectAmt == midAccBalance && afterContractBalance + collectAmt == midContractBalance)
        );
    }

    // allow receiving Ether so this contract can fund Put
    receive() external payable {}
}
